import { NextResponse } from 'next/server';

const MOCK_DISCOUNTS = [
  { id: 'DSC-001', code: 'SUMMER2024', type: 'percentage' as const, value: 20, usageCount: 156, usageLimit: 500, status: 'active' as const, startDate: '2024-01-01', endDate: '2024-03-31' },
  { id: 'DSC-002', code: 'NEWUSER50', type: 'fixed' as const, value: 50, usageCount: 89, usageLimit: 1000, status: 'active' as const, startDate: '2024-01-01', endDate: '2024-12-31' },
  { id: 'DSC-003', code: 'VIP15OFF', type: 'percentage' as const, value: 15, usageCount: 45, usageLimit: 100, status: 'expired' as const, startDate: '2023-12-01', endDate: '2023-12-31' }
];

let discounts = [...MOCK_DISCOUNTS];

export async function GET() {
  try {
    return NextResponse.json(discounts);
  } catch (error) {
    console.error('[Discounts API] Error:', error);
    return NextResponse.json({ error: 'Failed to fetch discounts' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const newDiscount = {
      id: `DSC-${Date.now()}`,
      code: body.code,
      type: body.type,
      value: body.value,
      usageCount: 0,
      usageLimit: body.usageLimit,
      status: 'active' as const,
      startDate: body.startDate,
      endDate: body.endDate
    };
    discounts.push(newDiscount);
    return NextResponse.json(newDiscount);
  } catch (error) {
    console.error('[Discounts API] Error:', error);
    return NextResponse.json({ error: 'Failed to create discount' }, { status: 500 });
  }
}

export async function PUT(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    
    if (!id) {
      return NextResponse.json({ error: 'Discount ID is required' }, { status: 400 });
    }

    const body = await request.json();
    const index = discounts.findIndex(d => d.id === id);
    
    if (index === -1) {
      return NextResponse.json({ error: 'Discount not found' }, { status: 404 });
    }

    discounts[index] = { ...discounts[index], ...body };
    return NextResponse.json(discounts[index]);
  } catch (error) {
    console.error('[Discounts API] Error:', error);
    return NextResponse.json({ error: 'Failed to update discount' }, { status: 500 });
  }
}

export async function DELETE(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    
    if (!id) {
      return NextResponse.json({ error: 'Discount ID is required' }, { status: 400 });
    }

    const index = discounts.findIndex(d => d.id === id);
    if (index === -1) {
      return NextResponse.json({ error: 'Discount not found' }, { status: 404 });
    }

    discounts.splice(index, 1);
    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('[Discounts API] Error:', error);
    return NextResponse.json({ error: 'Failed to delete discount' }, { status: 500 });
  }
}
